/// <reference path="./worker-configuration.d.ts" />

import type FeedCrudManager from "@/server/feed/FeedCrudManager";
import type FeedDb from "@/server/feed/FeedDb";
import type {
  AdminProtectionStatus,
  FeedContent,
  OnboardingResult,
} from "./types";

declare module "react" {
  interface Component<P, S> {
    [member: string]: any;
  }
}

declare global {
  // The repository build configuration supplies defaults. Configurations
  // generated by `yarn manage` may override these deployment settings.
  interface Env {
    BETTER_AUTH_SECRET: string;
    DEPLOYMENT_ENVIRONMENT?: "preview" | "production";
    MICROFEED_ADMIN_AUTH_MODE?: "built-in" | "none";
    MICROFEED_ADMIN_PATH?: string;
    MICROFEED_CLOUDFLARE_ACCOUNT_ID?: string;
    MICROFEED_INSTANCE_ID?: string;
    MICROFEED_INSTANCE_NAME?: string;
    MICROFEED_R2_BUCKET_NAME?: string;
    MICROFEED_R2_SETUP_MODE?: "automatic" | "disabled";
    MICROFEED_WEBHOOK_QUEUE_ID?: string;
    MICROFEED_WEBHOOK_QUEUE_NAME?: string;
    MICROFEED_WEBHOOK_STATE?: "unprovisioned" | "enabled" | "disabled";
    MICROFEED_WORKER_NAME?: string;
    MICROFEED_SETUP_ADMIN_EMAIL?: string;
    MICROFEED_SETUP_ADMIN_PASSWORD?: string;
    MICROFEED_SETUP_ADMIN_PASSWORD_CONFIRMATION?: string;
    TEST_MIGRATIONS?: D1Migration[];
    UPLOAD_SIGNING_KEY: string;
  }

  namespace Cloudflare {
    interface Env {
      BETTER_AUTH_SECRET: string;
      DEPLOYMENT_ENVIRONMENT?: "preview" | "production";
      MICROFEED_ADMIN_AUTH_MODE?: "built-in" | "none";
      MICROFEED_ADMIN_PATH?: string;
      MICROFEED_CLOUDFLARE_ACCOUNT_ID?: string;
      MICROFEED_INSTANCE_ID?: string;
      MICROFEED_INSTANCE_NAME?: string;
      MICROFEED_R2_BUCKET_NAME?: string;
      MICROFEED_R2_SETUP_MODE?: "automatic" | "disabled";
      MICROFEED_WEBHOOK_QUEUE_ID?: string;
      MICROFEED_WEBHOOK_QUEUE_NAME?: string;
      MICROFEED_WEBHOOK_STATE?: "unprovisioned" | "enabled" | "disabled";
      MICROFEED_WORKER_NAME?: string;
      MICROFEED_SETUP_ADMIN_EMAIL?: string;
      MICROFEED_SETUP_ADMIN_PASSWORD?: string;
      MICROFEED_SETUP_ADMIN_PASSWORD_CONFIRMATION?: string;
      TEST_MIGRATIONS?: D1Migration[];
      UPLOAD_SIGNING_KEY: string;
    }
  }

  namespace App {
    interface Locals {
      adminProtection?: AdminProtectionStatus;
      authSession?: import("better-auth").Session;
      authUser?: import("better-auth").User;
      feedContent?: FeedContent;
      feedCrud?: FeedCrudManager;
      feedDb?: FeedDb;
      onboardingResult?: OnboardingResult;
      publicBucketUrl?: string;
      // RBAC (microfeed adaptation): resolved by src/middleware.ts.
      rbacPermissions?: Set<string>;
      rbacAdminLoginAllowed?: boolean;
      rbacMustChangePassword?: boolean;
      rbacDeviceRevoked?: boolean;
      rbacBanned?: boolean;
      /**
       * 调用方是否持「会员」角色（`ext_roles.is_member` 的并集，migration 0144）。
       * 由 App 登录凭证鉴权时与权限码同一趟查询得出，内容端点据此决定要不要
       * 收录会员书；后台会话路径不设这个字段。
       */
      appMember?: boolean;
    }
  }
}

export {};
